// dayTitle is what a day's bar says when pointed at.
func dayTitle(d ops.UptimeDay) string {
	if d.Checks == 0 {
		return d.Day.Format("Jan 2") + ": no checks"
	}
	return fmt.Sprintf("%s: %.2f%%", d.Day.Format("Jan 2"), d.Pct)
}

